import Image from "next/image";
import Link from "next/link";
import type { Prisma } from "@prisma/client";
import { Plus } from "lucide-react";
import { db } from "@/lib/db";
import { formatINR } from "@/lib/money";
import { cn } from "@/lib/utils";
import { PageHeader, Table, td } from "@/components/admin/ui";
import { DeleteProductButton, PriceInput, StockInput, ToggleSwitch } from "@/components/admin/ProductRowActions";

export default async function AdminProducts({ searchParams }: PageProps<"/admin/products">) {
  const sp = await searchParams;
  const q = typeof sp.q === "string" ? sp.q.trim() : "";
  const cat = typeof sp.category === "string" ? sp.category : "";
  const stock = sp.stock === "low" ? "low" : sp.stock === "out" ? "out" : "";
  const status = sp.status === "active" || sp.status === "hidden" ? sp.status : "";
  const saved = typeof sp.saved === "string" ? sp.saved : null;

  const where: Prisma.ProductWhereInput = {
    ...(q ? { OR: [{ name: { contains: q, mode: "insensitive" } }, { sku: { contains: q, mode: "insensitive" } }] } : {}),
    ...(cat ? { OR: [{ categoryId: cat }, { category: { parentId: cat } }] } : {}),
    ...(stock === "out" ? { stock: 0 } : {}),
    ...(status ? { isActive: status === "active" } : {}),
  };
  const [products, categories] = await Promise.all([
    db.product.findMany({
      where,
      include: { category: { select: { name: true } }, images: { take: 1, orderBy: { sortOrder: "asc" } }, _count: { select: { orderItems: true } } },
      orderBy: { updatedAt: "desc" },
      take: 300,
    }),
    db.category.findMany({ where: { parentId: null }, orderBy: { sortOrder: "asc" } }),
  ]);
  const list = stock === "low" ? products.filter((p) => p.stock <= p.lowStockThreshold) : products;

  return (
    <>
      <PageHeader
        title="Products"
        description={`${list.length} products · edit price and stock inline; changes are live instantly`}
        actions={<Link href="/admin/products/new" className="btn-primary"><Plus className="h-4 w-4" /> Add product</Link>}
      />
      {saved && <p className="mb-4 rounded-md bg-success/10 p-3 text-sm text-success">“{saved}” saved and published.</p>}
      <form className="mb-4 flex flex-wrap gap-2">
        <input name="q" defaultValue={q} placeholder="Search name or SKU" className="input max-w-xs" />
        <select name="category" defaultValue={cat} className="input w-auto">
          <option value="">All categories</option>
          {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>
        <select name="stock" defaultValue={stock} className="input w-auto">
          <option value="">Any stock</option><option value="low">Low stock</option><option value="out">Out of stock</option>
        </select>
        <select name="status" defaultValue={status} className="input w-auto">
          <option value="">Any status</option><option value="active">Published</option><option value="hidden">Hidden</option>
        </select>
        <button className="btn-dark">Filter</button>
      </form>
      <div className="rounded-lg border border-line bg-white">
        <Table head={["", "Product", "Category", "Price", "MRP", "Stock", "Sold", "Live", "Featured", ""]}>
          {list.map((p) => (
            <tr key={p.id} className={cn(!p.isActive && "opacity-60")}>
              <td className={td}><div className="relative h-12 w-12 rounded bg-paper">{p.images[0] && <Image src={p.images[0].url} alt="" fill sizes="48px" className="object-contain p-0.5" />}</div></td>
              <td className={td}>
                <Link href={`/admin/products/${p.id}`} className="font-medium hover:text-maroon">{p.name}</Link>
                <span className="block text-xs text-muted">{p.sku}{p.emiEligible && " · EMI"}{p.engravingAvailable && " · Engraving"}</span>
              </td>
              <td className={cn(td, "text-muted")}>{p.category.name}</td>
              <td className={td}><PriceInput id={p.id} price={p.price} /></td>
              <td className={cn(td, "tabular-nums text-muted")}>{formatINR(p.mrp)}</td>
              <td className={td}>
                <StockInput id={p.id} stock={p.stock} />
                {p.stock <= p.lowStockThreshold && <span className={cn("block text-xs font-semibold", p.stock === 0 ? "text-danger" : "text-warn")}>{p.stock === 0 ? "Out of stock" : "Low"}</span>}
              </td>
              <td className={cn(td, "tabular-nums")}>{p._count.orderItems}</td>
              <td className={td}><ToggleSwitch id={p.id} field="isActive" value={p.isActive} label="Published" /></td>
              <td className={td}><ToggleSwitch id={p.id} field="isFeatured" value={p.isFeatured} label="Featured" /></td>
              <td className={cn(td, "whitespace-nowrap")}>
                <Link href={`/product/${p.slug}`} target="_blank" className="mr-3 text-xs text-maroon hover:underline">View</Link>
                <DeleteProductButton id={p.id} name={p.name} />
              </td>
            </tr>
          ))}
        </Table>
        {!list.length && <p className="p-8 text-center text-sm text-muted">No products match these filters.</p>}
      </div>
    </>
  );
}
